def Q(x):
    # Q(x) = 64x^2 + 1280x - 486
    return 64 * x**2 + 1280 * x - 486

k_values = [-3, -2, -1, 0, 1, 2, 3]
results = {}
for k in k_values:
    results[k] = Q(k)

print("Calculated Q(k) values:")
for k, value in results.items():
    print(f"Q({k}) = {value}")

# Check for GP among consecutive values (k=-3 to k=3)
values_sequence = [results[k] for k in k_values]
print("\nSequence of values (k=-3 to k=3):")
print(values_sequence)

# Check consecutive triplets for common ratio R
triplets = []
for i in range(len(values_sequence) - 2):
    a, b, c = values_sequence[i], values_sequence[i+1], values_sequence[i+2]
    if a != 0 and b != 0:
        ratio1 = b / a
        ratio2 = c / b
        if abs(ratio1 - ratio2) < 1e-9:
            triplets.append((a, b, c, ratio1))

if triplets:
    print("\nFound a geometric progression of length 3 or more (consecutive k):")
    for t in triplets:
        print(f"Sequence: {t[0]}, {t[1]}, {t[2]} with ratio R = {t[3]}")
else:
    print("\nNo geometric progression of length 3 or more found among consecutive values.")
